// 04 - SD Card Log: the FAT32 mount and the write/read-back of the log.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "eth_helpers.hpp"

using namespace os::rtos;
using namespace mtp_eth;

// 04 - SD Card Log
// ===========================================================================
mt::static_suite suite_sd_log{
  "04 - SD Card Log", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("SD card FAT32 volume mounted by background thread", [] (auto& t) {
      const std::uint32_t start = platform::millis ();
      while (!app::saver_ready () && platform::millis () - start < 10000u)
        {
          net::poll ();
          sysclock.sleep_for (2);
        }
      t.expect (app::saver_ready ()) << "SD saver thread completed card init";
      t.expect (!app::saver_failed ())
          << "FAT32 volume mounted and tests/ directory ready";
    });

    ts.test ("network run log saved to tests/MTPNET.LOG and verified by read-back",
             [] (auto& t) {
               app::log ("verdict: PASS\n");
               const std::uint32_t sz = app::log_size ();
               const bool saved
                   = app::save_and_wait ("MTPNET.LOG", app::log_text (), sz);
               std::printf ("# SD log: tests/MTPNET.LOG, %u bytes, saved=%s\n",
                            static_cast<unsigned> (sz), saved ? "yes" : "no");
               t.expect (mt::gt (sz, 0u))
                   << fmt ("log buffer holds %u bytes", sz);
               t.expect (saved)
                   << "written to tests/MTPNET.LOG and verified byte-for-byte";
             });
  }
};
